  Image indicator;float indicatorX;bool located;GameRuntime game;public Sprite[] ResourceIcons;public LaboratoryView Laboratory;public void Initialize(GameRuntime runtime){game=runtime;var rootCanvas=game.Content.GetComponentInParent<Canvas>().rootCanvas;if(rootCanvas.GetComponent<MobileCanvasScale>()==null)rootCanvas.gameObject.AddComponent<MobileCanvasScale>();lastResets=game.State.Prestige.resets;lastPrestigeRevision=game.State.Prestige.revision;foreach(var value in new[]{game.Credits,game.Compute,game.Users,game.Data}){value.resizeTextForBestFit=true;value.resizeTextMinSize=10;value.fontSize=12;value.resizeTextMaxSize=12;value.horizontalOverflow=HorizontalWrapMode.Overflow;var resourceName=value.transform.parent.Find("ResourceName")?.GetComponent<Text>();if(resourceName!=null){resourceName.rectTransform.offsetMin=new Vector2(24,0);resourceName.rectTransform.offsetMax=new Vector2(-2,-1);resourceName.alignment=TextAnchor.MiddleLeft;resourceName.resizeTextForBestFit=true;resourceName.resizeTextMinSize=8;resourceName.resizeTextMaxSize=10;}}game.TrainingTab.gameObject.SetActive(false);ShopTab=Instantiate(game.ItemsTab,game.ItemsTab.transform.parent);ShopTab.name="ShopTab";ShopTab.onClick.RemoveAllListeners();ShopTab.onClick.AddListener(()=>game.UserShow("shop"));ShopTab.transform.Find("NavigationIcon").GetComponent<Image>().sprite=game.Users.transform.parent.Find("ResourceIcon").GetComponent<Image>().sprite;navigation=new[]{game.HardwareTab,game.ResearchTab,game.ItemsTab,game.PrestigeTab,ShopTab};for(int i=0;i<navigation.Length;i++)navigation[i].transform.SetSiblingIndex(i);surfaces=navigation.Select(b=>b.GetComponent<Image>()).ToArray();labels=navigation.Select(b=>b.GetComponentsInChildren<Text>()).ToArray();foreach(var b in navigation){var line=b.transform.Find("ActiveLine");if(line!=null)line.gameObject.SetActive(false);}var receipts=gameObject.AddComponent<RewardPresentation>();receipts.Initialize(game);Laboratory.Initialize(game);var menu=gameObject.AddComponent<GameMenu>();menu.Initialize(game);var safe=Laboratory.GetComponentInParent<SafeArea>().transform;var tabs=safe.Find("Tabs");indicator=WorkshopUIFactory.Node("ActiveNavigationMarker",tabs,typeof(Image),typeof(LayoutElement)).GetComponent<Image>();indicator.GetComponent<LayoutElement>().ignoreLayout=true;indicator.raycastTarget=false;indicator.color=GameTheme.Accent;indicator.rectTransform.anchorMin=indicator.rectTransform.anchorMax=new Vector2(.5f,0);indicator.rectTransform.sizeDelta=new Vector2(52,3);var button=safe.Find("Resources/Menu")??safe.Find("Header/Menu");if(button!=null)button.GetComponent<Button>().onClick.AddListener(menu.Open);}
  public static string ResourceAmount(ScientificNumber amount,Text label,string mode,string language){string text=NumberFormatting.Format(amount,mode,language);float available=label.rectTransform.rect.width;if(available<1||mode!="auto")return text;var settings=label.GetGenerationSettings(Vector2.zero);settings.resizeTextForBestFit=false;settings.fontSize=12;settings.horizontalOverflow=HorizontalWrapMode.Overflow;float Width(string value)=>label.cachedTextGeneratorForLayout.GetPreferredWidth(value,settings)/label.pixelsPerUnit;if(Width(text)<=available)return text;for(int digits=2;digits>=0;digits--){text=NumberFormatting.Format(amount,"scientific",language,digits);if(Width(text)<=available)break;}return text;}
  public void RefreshNavigation()=>LateUpdate();
  void LateUpdate(){if(game?.State==null)return;var s=game.State;if(lastResets==0&&s.Prestige.resets>0&&s.Prestige.revision>lastPrestigeRevision){unlockNote=StorefrontUI.Info(game,"MiraGumballUnlock","Dr. Mira Voss",s.Settings.language=="de"?"Der Gumball-Automat ist jetzt bereit! Öffne ihn am rechten Laborrand oder im Shop. Ziehe mit Gems oder löse einen Gutschein ein. Alle Chancen findest du beim Info-Button.":"The Gumball machine is ready! Open it at the right edge of the lab or in the shop. Draw with Gems or redeem a voucher. The info button shows all odds.");}lastResets=s.Prestige.resets;lastPrestigeRevision=s.Prestige.revision;bool unlocked=ProgressionVisibility.Prestige(s);if(prestigeVisible!=unlocked||game.PrestigeTab.gameObject.activeSelf!=unlocked){prestigeVisible=unlocked;game.PrestigeTab.gameObject.SetActive(unlocked);located=false;}if(language!=s.Settings.language){language=s.Settings.language;for(int i=0;i<5;i++)navigation[i].GetComponentInChildren<Text>().text=NavigationWords.Label(names[i],language);}string route=game.NavigationTab=="training"?"hardware":new[]{"models","challenges"}.Contains(game.NavigationTab)?"research":new[]{"market","gems","store","ads","seasons"}.Contains(game.NavigationTab)?"shop":game.NavigationTab;string selected=Array.IndexOf(names,route)>=0?route:(selection??"hardware");if(selected=="prestige"&&!unlocked)selected="hardware";int index=Array.IndexOf(names,selected);if(selection!=selected){selection=selected;for(int i=0;i<5;i++){bool active=i==index;surfaces[i].color=active?GameTheme.Hex("17353F"):Color.clear;foreach(var text in labels[i])text.color=active?GameTheme.Accent:GameTheme.Muted;}}bool lab=game.CurrentTab=="hardware";if(Laboratory.gameObject.activeSelf!=lab)Laboratory.gameObject.SetActive(lab);if(indicator!=null){var parent=(RectTransform)indicator.transform.parent;float goal=parent.InverseTransformPoint(navigation[index].transform.position).x;bool reduced=s.Workshop.reducedMotion||!s.Settings.effects;if(!located||reduced||Mathf.Abs(goal-indicatorX)<.1f)indicatorX=goal;else indicatorX=Mathf.Lerp(indicatorX,goal,1-Mathf.Exp(-Time.unscaledDeltaTime*20));located=true;indicator.rectTransform.anchoredPosition=new Vector2(Mathf.Round(indicatorX),3);indicator.rectTransform.sizeDelta=new Vector2(((RectTransform)navigation[index].transform).rect.width-20,3);}}
  void OnDestroy(){if(unlockNote!=null)Destroy(unlockNote);}
